/** Existing-shot editing owns a draft; only Save writes parameters and the effective capture time. */
final class ExposureEditor {
    private final Activity activity;private final LogStore logs;private final LogStore.Shot original;private final Bundle draft;
    private final Runnable saved,cancel;private final Consumer<Intent> launch;private final LinearLayout root;
    private final ArrayList<Dialog> dialogs=new ArrayList<>();private ScrollView page;private Button save;
    private boolean building;private PresetEditor presetEditor;private MemoTags tags;private TextView moreSummary;
    ExposureEditor(Activity activity,LogStore logs,LogStore.Shot shot,Bundle draft,Runnable saved,Runnable cancel,Consumer<Intent> launch){
        this.activity=activity;this.logs=logs;original=shot;this.draft=draft;this.saved=saved;this.cancel=cancel;this.launch=launch;
        if(!draft.containsKey("capturedAt"))draft.putLong("capturedAt",shot.captured);root=column();render();
    }
    View view(){return root;}
    private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    private int color(int id){return activity.getColor(id);}
    private LinearLayout column(){LinearLayout v=new LinearLayout(activity);v.setOrientation(LinearLayout.VERTICAL);return v;}
    private LinearLayout row(){LinearLayout v=new LinearLayout(activity);v.setGravity(Gravity.CENTER_VERTICAL);v.setBaselineAligned(false);return v;}
    private TextView text(String value,int size,boolean bold){TextView v=new TextView(activity);v.setText(value);v.setTextSize(size);v.setTextColor(color(R.color.ui_ink));v.setTypeface(Typeface.create(bold?"sans-serif-medium":"sans-serif",0));return v;}
    private TextView hint(String value){TextView v=text(value,12,false);v.setTextColor(color(R.color.ui_muted));v.setLineSpacing(dp(2),1);return v;}
    private GradientDrawable surface(int fill,int radius,int line){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));if(line!=0)d.setStroke(dp(1),line);return d;}
    private Button button(String label,boolean primary,Runnable action){Button b=UiSpacing.button(activity);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setSingleLine(true);b.setHorizontallyScrolling(false);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(10),dp(8),dp(10),dp(8));b.setMinHeight(dp(48));b.setMinimumHeight(dp(48));b.setTextColor(color(primary?R.color.ui_on_accent:R.color.ui_accent));b.setBackgroundTintList(null);b.setBackground(surface(color(primary?R.color.ui_accent:R.color.ui_card),8,primary?0:color(R.color.ui_outline)));b.setStateListAnimator(null);b.setElevation(0);b.setContentDescription(label);b.setOnClickListener(v->action.run());return b;}
    private Button link(String label,Runnable action){Button b=button(label,false,action);b.setBackgroundColor(android.graphics.Color.TRANSPARENT);return b;}
    private void gap(LinearLayout parent,int height){parent.addView(new View(activity),new LinearLayout.LayoutParams(1,dp(height)));}
    private void line(LinearLayout parent){View v=new View(activity);v.setBackgroundColor(color(R.color.ui_outline));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(1));p.setMargins(dp(14),0,dp(14),0);parent.addView(v,p);}
    private LinearLayout group(LinearLayout parent){LinearLayout v=column();v.setBackground(surface(color(R.color.ui_card),10,0));parent.addView(v,new LinearLayout.LayoutParams(-1,-2));return v;}
    private void heading(LinearLayout parent,String title){gap(parent,20);TextView label=text(title,15,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(10);parent.addView(label,p);}
    private String value(String key){return draft.getString(key,"");}
    boolean changed(){return draft.getLong("capturedAt")!=original.captured||!value("aperture").equals(original.aperture)||!value("shutter").equals(original.shutter)||!value("lens").equals(original.lens)||!value("ev").equals(original.ev)||!value("filters").equals(original.filters)||!value("memo").equals(original.memo);}
    private void dirty(){if(save!=null){save.setEnabled(changed());save.setAlpha(changed()?1f:.45f);}if(moreSummary!=null){ArrayList<String> fields=new ArrayList<>();for(String key:new String[]{"lens","ev","filters"})if(!value(key).trim().isEmpty())fields.add(value(key));moreSummary.setText(fields.isEmpty()?"未填写":String.join(" · ",fields));}}
    private void closeSheet(Dialog d,String key){draft.remove(key);if(d!=null)d.dismiss();}
    void dispose(){for(Dialog d:dialogs)if(d.isShowing())d.dismiss();if(presetEditor!=null)presetEditor.dispose();}
    private AlertDialog show(AlertDialog d){dialogs.add(d);d.show();return d;}
    private Dialog sheet(String title,LinearLayout content,String key){
        Dialog d=new Dialog(activity,R.style.FilmDialog);d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout outer=column();outer.setPadding(dp(16),dp(8),dp(16),dp(16));outer.setBackground(surface(color(R.color.ui_background),20,0));
        View grip=new View(activity);grip.setBackground(surface(color(R.color.ui_outline),2,0));LinearLayout.LayoutParams gripSize=new LinearLayout.LayoutParams(dp(32),dp(3));gripSize.gravity=Gravity.CENTER_HORIZONTAL;gripSize.bottomMargin=dp(8);outer.addView(grip,gripSize);
        LinearLayout header=row();header.addView(text(title,20,true),new LinearLayout.LayoutParams(0,-2,1));header.addView(link("取消",()->closeSheet(d,key)));outer.addView(header);
        ScrollView scroll=new ScrollView(activity);scroll.setFillViewport(false);scroll.addView(content);outer.addView(scroll,new LinearLayout.LayoutParams(-1,-2));d.setContentView(outer);d.setOnCancelListener(v->draft.remove(key));dialogs.add(d);d.show();Window w=d.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setGravity(Gravity.BOTTOM);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);w.setLayout(-1,-2);}
        outer.post(()->{if(!d.isShowing()||w==null)return;int limit=Math.round(activity.getResources().getDisplayMetrics().heightPixels*.88f);outer.measure(View.MeasureSpec.makeMeasureSpec(activity.getResources().getDisplayMetrics().widthPixels,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));if(outer.getMeasuredHeight()>limit){scroll.setLayoutParams(new LinearLayout.LayoutParams(-1,0,1));w.setLayout(-1,limit);}});return d;
    }
    private void render(){
        building=true;save=null;moreSummary=null;root.removeAllViews();root.setBackgroundColor(color(R.color.ui_background));
        View nav=LibraryUi.header(activity,"编辑曝光",cancel,LibraryUi.icon(activity,0xe1fe,"曝光编辑更多操作",this::menu));Button back=(Button)((ViewGroup)nav).getChildAt(1);back.setTypeface(Typeface.DEFAULT);back.setText("取消");back.setTextSize(14);back.setContentDescription("取消");root.addView(nav);
        page=new ScrollView(activity);LinearLayout body=column();body.setPadding(dp(16),dp(8),dp(16),dp(24));page.addView(body);root.addView(page,new LinearLayout.LayoutParams(-1,0,1));page.setOnScrollChangeListener((v,x,y,oldX,oldY)->draft.putInt("editorScroll",y));
        LogStore.Roll roll=logs.roll(original.rollId);body.addView(hint(String.format(Locale.CHINA,"第%02d张 · %s",original.frame,roll.stock)));gap(body,4);body.addView(hint((roll.camera.isEmpty()?"未选择相机":roll.camera)+" · ISO "+(roll.iso>0?roll.iso:"未记")));
        gap(body,18);LinearLayout parameterHeading=row();parameterHeading.addView(text("曝光参数",15,true),new LinearLayout.LayoutParams(0,-2,1));Button quick=link("快速填入 ›",()->{draft.putBoolean("quickOpen",true);quickFill();});quick.setTag("editor-quick-fill");parameterHeading.addView(quick);body.addView(parameterHeading);
        LinearLayout params=group(body),pair=row();parameterCell(pair,"光圈",ExposureChoices.apertureLabel(value("aperture")),true);View vertical=new View(activity);vertical.setBackgroundColor(color(R.color.ui_outline));pair.addView(vertical,new LinearLayout.LayoutParams(dp(1),dp(42)));parameterCell(pair,"快门",value("shutter").isEmpty()?"—":value("shutter"),false);params.addView(pair);line(params);
        LinearLayout expand=row();expand.setMinimumHeight(dp(52));expand.setPadding(dp(14),0,dp(14),0);expand.addView(text("更多参数",14,false));moreSummary=hint("");moreSummary.setSingleLine(true);moreSummary.setHorizontallyScrolling(false);moreSummary.setEllipsize(android.text.TextUtils.TruncateAt.END);moreSummary.setGravity(Gravity.RIGHT);LinearLayout.LayoutParams summarySize=new LinearLayout.LayoutParams(0,-2,1);summarySize.leftMargin=dp(10);expand.addView(moreSummary,summarySize);expand.addView(hint("  ›"));expand.setContentDescription("展开或收起镜头、曝光补偿和滤镜");expand.setFocusable(true);params.addView(expand);
        LinearLayout extra=column();extra.setPadding(dp(14),0,dp(14),dp(8));params.addView(extra);extra.setVisibility(draft.getBoolean("advanced",false)?View.VISIBLE:View.GONE);expand.setOnClickListener(v->{boolean opened=extra.getVisibility()!=View.VISIBLE;draft.putBoolean("advanced",opened);extra.setVisibility(opened?View.VISIBLE:View.GONE);});
        editField(extra,"镜头 / 焦距","lens","未填写");Button choose=link("从器材选择镜头 ›",this::chooseLens);extra.addView(choose);editField(extra,"曝光补偿","ev","例如 +1/3 EV");editField(extra,"滤镜","filters","例如 ND8");
        heading(body,"拍摄信息");LinearLayout information=group(body);TextView when=entry(information,"拍摄时间",date(draft.getLong("capturedAt")),zoneLabel()+" · 记录时区",()->{draft.putBoolean("timeOpen",true);timeSheet();});when.setTag("editor-capture-time");line(information);
        entry(information,"拍摄位置",original.lat==null?"历史记录未含定位":"已保存位置",original.lat==null?"本次编辑保留原记录":(original.accuracy==null?"保留原始坐标":String.format(Locale.CHINA,"精度约 %.0f 米",original.accuracy)),()->show(new AlertDialog.Builder(activity).setTitle("已保存的拍摄位置").setMessage(original.lat==null?"这条历史记录没有坐标。编辑参数和时间不需要重新定位。":String.format(Locale.CHINA,"%.6f, %.6f\n%s",original.lat,original.lon,"修改时间不会改变坐标或定位时间。")).setPositiveButton("知道了",null).create()));gap(body,6);body.addView(hint("修改时间不会改变已保存位置"));
        heading(body,"备注与标签");LinearLayout notes=group(body);notes.setPadding(dp(12),dp(6),dp(12),dp(8));tags=new MemoTags(value("memo"));EditText memo=new EditText(activity);memo.setText(tags.freeText);memo.setHint("记录光线、场景或拍摄想法…");memo.setTextColor(color(R.color.ui_ink));memo.setHintTextColor(color(R.color.ui_muted));memo.setTextSize(15);memo.setMinLines(2);memo.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);memo.setBackgroundColor(android.graphics.Color.TRANSPARENT);memo.setTag("editor-memo");notes.addView(memo,new LinearLayout.LayoutParams(-1,-2));memo.addTextChangedListener(watch(()->{draft.putString("memo",tags.memo(memo.getText().toString()));dirty();}));
        LinearLayout labels=column();String[] names={"人像","风景","街头","夜景","建筑","纪实"};ArrayList<String> selected=new ArrayList<>();for(int i=0;i<names.length;i++)if(tags.contains(MemoTags.KEYS.get(i)))selected.add(names[i]);if(!selected.isEmpty()){TextView selectedText=text(String.join(" · ",selected),13,false);selectedText.setTextColor(color(R.color.ui_accent));labels.addView(selectedText);}labels.addView(link("＋ 添加标签",()->{draft.putBoolean("tagsOpen",true);tagSheet();}));notes.addView(labels);
        LinearLayout footer=column();footer.setPadding(dp(16),dp(8),dp(16),dp(12));save=button("保存修改",true,this::save);save.setTag("editor-save");footer.addView(save,new LinearLayout.LayoutParams(-1,-2));root.addView(footer);building=false;dirty();int position=draft.getInt("editorScroll",0);page.post(()->page.scrollTo(0,position));
        if(draft.containsKey("presetForm"))root.post(()->showPresetForm(draft.getBundle("presetForm")));else if(draft.getBoolean("timeOpen",false))root.post(this::timeSheet);else if(draft.getBoolean("quickOpen",false))root.post(this::quickFill);else if(draft.getBoolean("tagsOpen",false))root.post(this::tagSheet);
    }
    private TextWatcher watch(Runnable action){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){if(!building)action.run();}public void afterTextChanged(Editable e){}};}
    private void editField(LinearLayout parent,String label,String key,String placeholder){LinearLayout row=row();row.setMinimumHeight(dp(48));TextView name=hint(label);row.addView(name,new LinearLayout.LayoutParams(dp(84),-2));EditText edit=new EditText(activity);edit.setText(value(key));edit.setHint(placeholder);edit.setTextSize(15);edit.setSingleLine(true);edit.setTextColor(color(R.color.ui_ink));edit.setHintTextColor(color(R.color.ui_muted));edit.setBackgroundTintList(android.content.res.ColorStateList.valueOf(color(R.color.ui_outline)));edit.setContentDescription(label);edit.setTag("editor-"+key);row.addView(edit,new LinearLayout.LayoutParams(0,-2,1));parent.addView(row);edit.addTextChangedListener(watch(()->{draft.putString(key,edit.getText().toString());draft.remove("preset");dirty();}));}
    private TextView entry(LinearLayout group,String label,String current,String subtitle,Runnable click){
        LinearLayout item=column();item.setPadding(dp(14),dp(12),dp(14),dp(12));LinearLayout top=row();TextView name=text(label,14,false),v=text(current+"  ›",14,false);
        boolean stacked=activity.getResources().getConfiguration().fontScale>1.3f&&activity.getResources().getConfiguration().screenWidthDp<360;
        if(stacked){top.setOrientation(LinearLayout.VERTICAL);top.addView(name,new LinearLayout.LayoutParams(-1,-2));gap(top,6);top.addView(v,new LinearLayout.LayoutParams(-1,-2));}
        else{name.setSingleLine(true);name.setHorizontallyScrolling(false);name.setEllipsize(android.text.TextUtils.TruncateAt.END);top.addView(name,new LinearLayout.LayoutParams(0,-2,1));v.setGravity(Gravity.RIGHT);LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(0,-2,2);size.leftMargin=dp(12);top.addView(v,size);}
        item.addView(top);if(!subtitle.isEmpty()){gap(item,5);item.addView(hint(subtitle));}item.setMinimumHeight(dp(56));item.setFocusable(true);item.setContentDescription(label+"，"+current);item.setOnClickListener(w->click.run());group.addView(item);return v;
    }
    private void parameterCell(LinearLayout pair,String label,String value,boolean aperture){LinearLayout cell=column();cell.setPadding(dp(14),dp(14),dp(8),dp(14));cell.addView(hint(label));gap(cell,5);TextView number=text(value,26,true);number.setSingleLine(true);number.setHorizontallyScrolling(false);number.setAutoSizeTextTypeUniformWithConfiguration(14,26,1,android.util.TypedValue.COMPLEX_UNIT_SP);cell.addView(number);cell.setMinimumHeight(dp(82));cell.setFocusable(true);cell.setContentDescription("修改"+label+"，"+value);cell.setTag(aperture?"editor-aperture":"editor-shutter");cell.setOnClickListener(v->parameterPicker(aperture));pair.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}
    private void parameterPicker(boolean aperture){String key=aperture?"aperture":"shutter",title=aperture?"光圈":"快门";ArrayList<String> values=ExposureChoices.values(aperture,value(key));String[] labels=new String[values.size()];for(int i=0;i<labels.length;i++)labels[i]=aperture?ExposureChoices.apertureLabel(values.get(i)):values.get(i);show(new AlertDialog.Builder(activity).setTitle(title).setSingleChoiceItems(labels,values.indexOf(value(key)),(d,which)->{draft.putString(key,ExposureChoices.toggle(value(key),values.get(which)));draft.remove("preset");d.dismiss();render();}).setNeutralButton("自定义",(d,w)->customParameter(aperture)).setNegativeButton("取消",null).create());}
    private void customParameter(boolean aperture){EditText input=new EditText(activity);input.setSingleLine(true);input.setText(value(aperture?"aperture":"shutter"));input.setInputType(aperture?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_TEXT);LinearLayout wrap=column();wrap.setPadding(dp(20),dp(8),dp(20),0);wrap.addView(input);AlertDialog d=new AlertDialog.Builder(activity).setTitle(aperture?"自定义光圈":"快门秒数或分数").setView(wrap).setPositiveButton("应用到草稿",null).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{String result=aperture?PhotoMath.apertureValue(input.getText().toString()):PhotoMath.shutterChoice(PhotoMath.seconds(input.getText().toString()));draft.putString(aperture?"aperture":"shutter",result);draft.remove("preset");d.dismiss();render();}catch(IllegalArgumentException e){input.setError(e.getMessage());}}));dialogs.add(d);d.show();}
    private void chooseLens(){ArrayList<CatalogStore.Entry> entries=new CatalogStore(logs).entries("lens",false);String[] names=new String[entries.size()];for(int i=0;i<names.length;i++)names[i]=entries.get(i).name;if(names.length==0){Toast.makeText(activity,"器材中暂无镜头，可直接填写焦距或名称",Toast.LENGTH_LONG).show();return;}show(new AlertDialog.Builder(activity).setTitle("选择镜头").setItems(names,(d,index)->{draft.putString("lens",names[index]);draft.remove("preset");render();}).setNegativeButton("取消",null).create());}
    private void menu(){show(new AlertDialog.Builder(activity).setItems(new String[]{"清除曝光参数","原始记录信息"},(d,index)->{if(index==0){for(String key:new String[]{"aperture","shutter","lens","ev","filters"})draft.putString(key,"");draft.remove("preset");render();}else show(new AlertDialog.Builder(activity).setTitle("原始记录信息").setMessage("原始记录时间："+date(original.tapped)+"\n记录时偏移："+original.offset+" 秒\n"+zoneLabel()).setPositiveButton("知道了",null).create());}).create());}
    private String date(long millis){return Instant.ofEpochMilli(millis).atOffset(ZoneOffset.ofTotalSeconds(original.zone*60)).format(DateTimeFormatter.ofPattern("yyyy/MM/dd HH:mm:ss",Locale.CHINA));}
    private String zoneLabel(){return "UTC"+ZoneOffset.ofTotalSeconds(original.zone*60).toString().replace("Z","+00:00");}
    private void save(){if(!changed())return;try{logs.editCaptured(original,draft.getLong("capturedAt"),value("aperture"),value("shutter"),value("lens"),value("memo"),value("ev"),value("filters"));saved.run();}catch(Exception e){Toast.makeText(activity,"保存失败："+e.getMessage(),Toast.LENGTH_LONG).show();}}
    private void applyValues(String aperture,String shutter,String lens,String ev,String filters){String[] keys={"aperture","shutter","lens","ev","filters"},values={aperture,shutter,lens,ev,filters};for(int i=0;i<keys.length;i++)if(values[i]!=null&&!values[i].isEmpty())draft.putString(keys[i],values[i]);}
    private void quickFill(){
        if(!draft.getBoolean("quickOpen",false))return;LinearLayout body=column(),tabs=row(),list=column();boolean preset=draft.getBoolean("quickPresets",true);final Dialog[] dialog={null};
        for(String name:new String[]{"最近使用","参数预设"}){boolean select=name.equals("参数预设");Button b=button(name,false,()->{draft.putBoolean("quickPresets",select);if(dialog[0]!=null)dialog[0].dismiss();quickFill();});b.setSelected(select==preset);if(select==preset)b.setBackground(surface(color(R.color.ui_selected),8,0));tabs.addView(b,new LinearLayout.LayoutParams(0,-2,1));}body.addView(tabs);gap(body,8);body.addView(hint("点选应用到草稿，仅应用有值的参数"));gap(body,8);body.addView(list);
        if(preset){ArrayList<ExposurePresets> all=new ArrayList<>(Arrays.asList(ExposurePresets.ALL));for(PresetStore.Item p:new PresetStore(logs).list())all.add(p.preset());for(ExposurePresets p:all){entry(list,p.label,ExposureChoices.apertureLabel(p.aperture)+" · "+(p.shutter.isEmpty()?"快门未记":p.shutter),"",()->{applyValues(p.aperture,p.shutter,p.lens,"","");draft.putString("preset",p.id);closeSheet(dialog[0],"quickOpen");render();});line(list);}body.addView(link("管理预设 ›",()->{closeSheet(dialog[0],"quickOpen");managePresets();}));}
        else{for(LogStore.Shot shot:logs.recent())entry(list,"第"+shot.frame+"张",ExposureChoices.apertureLabel(shot.aperture)+" · "+(shot.shutter.isEmpty()?"快门未记":shot.shutter),shot.lens,()->{applyValues(shot.aperture,shot.shutter,shot.lens,shot.ev,shot.filters);draft.remove("preset");closeSheet(dialog[0],"quickOpen");render();});if(list.getChildCount()==0)list.addView(hint("暂无已填写的曝光参数"));}
        gap(body,12);line(body);heading(body,"辅助填写");LinearLayout tools=row();for(boolean meter:new boolean[]{false,true})tools.addView(button(meter?"测光填入 ›":"摄影计算 ›",false,()->{LogStore.Roll r=logs.roll(original.rollId);if(r.iso<1){Toast.makeText(activity,"请先填写有效胶片ISO",Toast.LENGTH_LONG).show();return;}closeSheet(dialog[0],"quickOpen");launch.accept(new Intent(activity,meter?MeterActivity.class:PhotoToolsActivity.class).putExtra(meter?"return_exposure":"return_result",true).putExtra("iso",r.iso).putExtra("aperture",value("aperture")).putExtra("shutter",value("shutter")).putExtra("comp",value("ev")).putExtra("ev100",draft.getDouble("meterEV",15)));}),new LinearLayout.LayoutParams(0,-2,1));body.addView(tools);gap(body,8);body.addView(hint("只填写参数，不改时间、位置或备注"));dialog[0]=sheet("快速填入",body,"quickOpen");
    }
    private void managePresets(){ArrayList<PresetStore.Item> items=new PresetStore(logs).list();String[] names=new String[items.size()];for(int i=0;i<names.length;i++)names[i]=items.get(i).name;show(new AlertDialog.Builder(activity).setTitle("自定义参数预设").setItems(names,(d,index)->presetForm(items.get(index).id)).setPositiveButton("新建预设",(d,w)->presetForm("")).setNegativeButton("关闭",null).create());}
    private void presetForm(String id){Bundle form=new Bundle();if(!id.isEmpty()){form.putBoolean("editing",true);form.putString("id",id);}draft.putBundle("presetForm",form);showPresetForm(form);}
    private void showPresetForm(Bundle form){presetEditor=new PresetEditor(activity,logs,form,()->draft.remove("presetForm"),()->{draft.remove("presetForm");render();});presetEditor.show();}
    private void tagSheet(){if(!draft.getBoolean("tagsOpen",false))return;String[] names={"人像","风景","街头","夜景","建筑","纪实"};MemoTags current=new MemoTags(value("memo"));boolean[] selected=draft.getBooleanArray("tagSelection");if(selected==null){selected=new boolean[names.length];for(int i=0;i<names.length;i++)selected[i]=current.contains(MemoTags.KEYS.get(i));}final boolean[] flags=selected;draft.putBooleanArray("tagSelection",flags);AlertDialog d=new AlertDialog.Builder(activity).setTitle("分类标签").setMultiChoiceItems(names,flags,(v,index,checked)->{flags[index]=checked;draft.putBooleanArray("tagSelection",flags);}).setPositiveButton("应用到草稿",(v,w)->{boolean changed=false;for(int i=0;i<flags.length;i++)if(current.contains(MemoTags.KEYS.get(i))!=flags[i]){current.toggle(MemoTags.KEYS.get(i));changed=true;}if(changed)draft.putString("memo",current.memo(current.freeText));draft.remove("tagsOpen");draft.remove("tagSelection");render();}).setNegativeButton("取消",(v,w)->{draft.remove("tagsOpen");draft.remove("tagSelection");}).create();d.setOnCancelListener(v->{draft.remove("tagsOpen");draft.remove("tagSelection");});dialogs.add(d);d.show();}
    private void timeSheet(){
        if(!draft.getBoolean("timeOpen",false))return;Bundle pending=draft.getBundle("timeDraft");if(pending==null){pending=new Bundle();pending.putLong("value",draft.getLong("capturedAt"));draft.putBundle("timeDraft",pending);}final Bundle state=pending;ZoneOffset zone=ZoneOffset.ofTotalSeconds(original.zone*60);LinearLayout body=column();TextView date=text("",15,false);date.setMinHeight(dp(48));date.setGravity(Gravity.CENTER_VERTICAL);date.setTag("time-date");body.addView(date);
        LocalDateTime initial=Instant.ofEpochMilli(state.getLong("value")).atOffset(zone).toLocalDateTime();LinearLayout wheels=row();NumberPicker[] pickers=new NumberPicker[3];String[] labels={"时","分","秒"};for(int i=0;i<3;i++){LinearLayout cell=column();TextView label=hint(labels[i]);label.setGravity(Gravity.CENTER);cell.addView(label);NumberPicker p=new NumberPicker(activity);p.setMinValue(0);p.setMaxValue(i==0?23:59);p.setFormatter(v->String.format(Locale.CHINA,"%02d",v));p.setValue(i==0?initial.getHour():i==1?initial.getMinute():initial.getSecond());p.setWrapSelectorWheel(true);p.setDescendantFocusability(ViewGroup.FOCUS_BLOCK_DESCENDANTS);p.setContentDescription("拍摄时间"+labels[i]);p.setTag("time-"+i);pickers[i]=p;cell.addView(p,new LinearLayout.LayoutParams(-1,dp(140)));wheels.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}body.addView(wheels);TextView preview=text("",14,true);preview.setTag("time-preview");TextView error=hint("");error.setTextColor(color(R.color.ui_error));boolean[] updating={false};
        Runnable refresh=()->{LocalDateTime t=Instant.ofEpochMilli(state.getLong("value")).atOffset(zone).toLocalDateTime();date.setText("日期    "+t.format(DateTimeFormatter.ofPattern("yyyy年M月d日",Locale.CHINA))+"  ›");updating[0]=true;pickers[0].setValue(t.getHour());pickers[1].setValue(t.getMinute());pickers[2].setValue(t.getSecond());updating[0]=false;preview.setText("将保存为  "+date(state.getLong("value")));};
        for(NumberPicker p:pickers)p.setOnValueChangedListener((v,old,value)->{if(updating[0])return;LocalDateTime t=Instant.ofEpochMilli(state.getLong("value")).atOffset(zone).toLocalDateTime().withHour(pickers[0].getValue()).withMinute(pickers[1].getValue()).withSecond(pickers[2].getValue());state.putLong("value",t.toInstant(zone).toEpochMilli());refresh.run();});
        date.setOnClickListener(v->{LocalDateTime t=Instant.ofEpochMilli(state.getLong("value")).atOffset(zone).toLocalDateTime();DatePickerDialog calendar=new DatePickerDialog(activity,(picker,y,m,d)->{try{LocalDateTime next=Instant.ofEpochMilli(state.getLong("value")).atOffset(zone).toLocalDateTime().withDayOfMonth(1).withYear(y).withMonth(m+1).withDayOfMonth(d);state.putLong("value",RecordRules.editedTime(next.toInstant(zone).toEpochMilli()));refresh.run();}catch(Exception invalid){error.setText("日期无效，请重新选择");}},t.getYear(),t.getMonthValue()-1,t.getDayOfMonth());dialogs.add(calendar);calendar.show();});
        gap(body,8);body.addView(hint("微调"));LinearLayout adjust=row();for(int seconds:new int[]{-10,-1,1,10}){Button b=button((seconds>0?"+":"")+seconds+"秒",false,()->{try{state.putLong("value",RecordRules.editedTime(Math.addExact(state.getLong("value"),seconds*1000L)));error.setText("");refresh.run();}catch(Exception invalid){error.setText("超出可编辑时间范围");}});b.setTextSize(12);b.setPadding(dp(4),dp(8),dp(4),dp(8));b.setTag("time-adjust:"+seconds);adjust.addView(b,new LinearLayout.LayoutParams(0,-2,1));}body.addView(adjust);gap(body,8);body.addView(hint(zoneLabel()+" · 沿用记录时区"));gap(body,12);body.addView(preview);gap(body,8);body.addView(hint("只改这张，不改变默认偏移或拍摄位置"));body.addView(error);final Dialog[] dialog={null};Button apply=button("应用到草稿",true,()->{try{draft.putLong("capturedAt",RecordRules.editedTime(state.getLong("value")));draft.remove("timeDraft");closeSheet(dialog[0],"timeOpen");render();}catch(IllegalArgumentException invalid){error.setText(invalid.getMessage());}});apply.setTag("time-apply");body.addView(apply,new LinearLayout.LayoutParams(-1,-2));body.addView(hint("回到页面保存后生效"));refresh.run();dialog[0]=sheet("拍摄时间",body,"timeOpen");dialog[0].setOnDismissListener(v->{if(!draft.getBoolean("timeOpen",false))draft.remove("timeDraft");});
    }
}
